(async () => {
  // Weapon WEIGHT QA (user, 2026-11-12: every weapon is light / medium / heavy and the class must change how the player moves).
  // Measures each fighter against the numbers of his weapon's class (fight_w/weapon_data.json, generated by gripref/render.mjs):
  //   blade  : fastest turn of the weapon inside each strike, deg/frame at 30 fps (heavy weapons must not whip round)
  //   strike : frames the swing itself takes (from 25 % of its peak speed to the hit)
  //   windup : seconds from the moment the weapon starts moving back to the hit (wind-back + swing). Approximate: the blade physics
  //            smooths the keys, so it reads shorter than the build's key spacing; it fails only under 60 % of the class value
  //   run    : top sustained root speed, blocks/s, against runBase x move
  //   combo  : most strikes in a row (gaps under 0.9 s)
  //   twirl  : show-off spins (none for heavy)
  // Weapons come from the build (weapons('golem_hammer', 'aegisblade') sets window.__weight) or from window.__qa_w = [A, B].
  //   node render.mjs eval "(window.__qa_w=['golem_hammer','aegisblade'], $(cat tools/weight_qa.js))"   with PAGE/QS as for a render
  const { cast, C, applyPose, THREE } = window.__probe, DATA = await fetch('/anim-test/fight_w/weapon_data.json').then(r => r.json());
  const names = window.__qa_w || (window.__weight && window.__weight.names); if (!names) return { error: 'no weapons: set window.__qa_w = [A, B] or call weapons() in the build' };
  const ev = C.events(), T0 = 0.1, T1 = C.TOTAL - 0.1, HZ = 30, out = {};
  ['A', 'B'].forEach((k, ki) => { const w = DATA.weapons[names[ki]]; if (!w) { out[k] = { error: 'no weight data for ' + names[ki] }; return; }
    const cls = DATA.classes[w.class], ts = [], dir = [], pos = [];
    for (let t = T0; t <= T1; t += 1 / HZ) { const p = C.pose(k, t); applyPose(cast[k], p); cast[k].root.updateMatrixWorld(true); const e = cast[k].weapon.matrixWorld.elements;
      ts.push(t); dir.push(new THREE.Vector3(e[4], e[5], e[6]).normalize()); pos.push([p.pos[0], p.pos[2]]); }
    const om = dir.map((d, i) => i ? Math.acos(Math.max(-1, Math.min(1, d.dot(dir[i - 1])))) * 180 / Math.PI : 0);          // deg/frame
    const sp = pos.map((q, i) => i ? Math.hypot(q[0] - pos[i - 1][0], q[1] - pos[i - 1][1]) * HZ : 0);                       // blocks/s
    const strikes = ev.swings.filter(s => s[1] === k).map(s => s[0]).filter(t => t > T0 + 0.3 && t < T1), rows = [];
    for (const t of strikes) { const i1 = Math.min(om.length - 1, Math.round((t - T0) * HZ)); let pk = 0, ip = i1;
      for (let i = Math.max(1, i1 - 8); i <= i1; i++) if (om[i] > pk) { pk = om[i]; ip = i; }
      let i0 = ip; while (i0 > 1 && om[i0 - 1] > pk * 0.25) i0--;                                                            // swing start
      const prev = strikes.filter(x => x < t - 1e-6).pop(), ilim = prev == null ? 1 : Math.round((prev - T0) * HZ) + 1;
      let iw = i0; while (iw > ilim && om[iw - 1] > 2 && i1 - iw < 45) iw--;                                                  // back through the wind-back motion to where the weapon was still
      rows.push({ t: +t.toFixed(2), blade: +pk.toFixed(1), strike: i1 - i0 + 1, windup: +((i1 - iw + 1) / HZ).toFixed(2) }); }
    const med = a => { const s = a.slice().sort((x, y) => x - y); return s.length ? s[s.length >> 1] : null; };
    const runT = ev.steps.filter(s => s[3] === k && s[5]).map(s => s[0]);                                                        // run-gait steps only: knockback slides and lunges are not running
    const fast = sp.filter((v, i) => v > 2.5 && runT.some(rt => Math.abs(rt - ts[i]) < 0.12)).sort((a, b) => a - b), run = fast.length ? fast[Math.floor(fast.length * 0.9)] : 0;
    let combo = 0, c = 0; strikes.forEach((t, i) => { c = i && t - strikes[i - 1] < 0.9 ? c + 1 : 1; combo = Math.max(combo, c); });
    const twirls = Math.round((ev.twirls || []).filter(x => x[1] === k).length / 2);                                              // events() lists every half turn
    const m = { weapon: w.name, class: w.class, heft: w.heft, strikes: rows.length, bladeMax: rows.length ? Math.max(...rows.map(r => r.blade)) : 0, bladeMedian: med(rows.map(r => r.blade)),
      strikeFramesMedian: med(rows.map(r => r.strike)), windupMedian: med(rows.map(r => r.windup)), runSpeed: +run.toFixed(2), combo, twirls };
    const want = { bladeDegPerFrame: cls.bladeDegPerFrame, strikeFrames: cls.strikeFrames, windup: cls.windup, runSpeed: +(DATA.runBase * cls.move).toFixed(2), combo: cls.combo, twirl: cls.twirl }, fails = [];
    if (m.bladeMedian > want.bladeDegPerFrame * 1.15) fails.push('blade turns ' + m.bladeMedian + ' deg/frame in a typical strike, class allows ' + want.bladeDegPerFrame);
        if (m.windupMedian != null && m.windupMedian < want.windup * 0.6) fails.push('wind-up ' + m.windupMedian + ' s, class needs ' + want.windup);
    if (m.runSpeed > want.runSpeed * 1.12) fails.push('runs at ' + m.runSpeed + ' blocks/s, class allows ' + want.runSpeed);
    if (m.combo > want.combo) fails.push(m.combo + ' strikes in a row, class allows ' + want.combo);
    if (m.twirls && !want.twirl) fails.push(m.twirls + ' twirl(s) with a heavy weapon');
    out[k] = { ...m, want, fails, perStrike: rows.map(r => r.t + ':' + r.blade + 'd/' + r.strike + 'f/' + r.windup + 's').join(' ') }; });
  return out;
})()
